class Solution:
    def findMin(self, nums: List[int]) -> int:
        lo, hi = 0, len(nums) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] > nums[hi]:        # mid 在前一段，最小值在右边
                lo = mid + 1
            else:                           # mid 在后一段，可能就是最小值
                hi = mid
        return nums[lo]

